// Where image files live: R2 (bucket binding MEDIA) or, for accounts without a payment method, Workers KV
// (binding MEDIA_KV, free tier: 1 GB, 1,000 writes/day). Keys are generated by the server only.

import type { Env } from "./env";

const KEY = /^(img|thumb)\/[0-9a-f]{32}\.(png|jpg)$/;

export interface MediaStore {
  kind: "r2" | "kv";
  put(key: string, data: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<{ body: ReadableStream | ArrayBuffer; contentType: string } | null>;
  delete(key: string): Promise<void>;
}

export function checkKey(key: string): string {
  if (!KEY.test(key)) throw new Error("Invalid object key.");
  return key;
}

export function mediaStore(env: Env): MediaStore | null {
  if (env.MEDIA) {
    const b = env.MEDIA;
    return {
      kind: "r2",
      async put(key, data, contentType) { await b.put(checkKey(key), data, { httpMetadata: { contentType } }); },
      async get(key) {
        const o = await b.get(checkKey(key));
        return o ? { body: o.body, contentType: o.httpMetadata?.contentType ?? "application/octet-stream" } : null;
      },
      async delete(key) { await b.delete(checkKey(key)); },
    };
  }
  if (env.MEDIA_KV) {
    const kv = env.MEDIA_KV;
    return {
      kind: "kv",
      async put(key, data, contentType) { await kv.put(checkKey(key), data, { metadata: { contentType } }); },
      async get(key) {
        const r = await kv.getWithMetadata<{ contentType: string }>(checkKey(key), "arrayBuffer");
        return r.value ? { body: r.value, contentType: r.metadata?.contentType ?? "application/octet-stream" } : null;
      },
      async delete(key) { await kv.delete(checkKey(key)); },
    };
  }
  return null;
}
